public void commit() throws IOException {
    close();
    if (ATOMIC_MOVE_NOT_SUPPORTED) {
        // We already know that this platform cannot honor ATOMIC_MOVE, so do not bother trying again.
        Files.move(tmpPath, destPath, StandardCopyOption.REPLACE_EXISTING);
    } else {
        try {
            // Try to make an atomic move.
            Files.move(tmpPath, destPath, StandardCopyOption.ATOMIC_MOVE);
        } catch (AtomicMoveNotSupportedException moveFailed) {
            // The filesystem does not support atomic moves at all, so remember that and downgrade every
            // subsequent write to the non-atomic replacement instead of retrying and logging every time.
            ATOMIC_MOVE_NOT_SUPPORTED = true;
            LOGGER.log(Level.WARNING, "Atomic move not supported, falling back to non-atomic move.", moveFailed);
            Files.move(tmpPath, destPath, StandardCopyOption.REPLACE_EXISTING);
        }
    }

